9702|# Opens a spool file EXCLUSIVELY (FileShare.None), retrying for $WaitMs (about 2 s; the bridge's
9703|# append 5 s - wave 28b, D6); $null when it does not exist ($Mode Open) or stays busy.
9704|function Open-TelemetrySpoolFile {
9705|    param([string]$Path, [System.IO.FileMode]$Mode = [System.IO.FileMode]::Open, [int]$WaitMs = 2000)
9706|    $watch = [System.Diagnostics.Stopwatch]::StartNew()
9707|    while ($true) {
9708|        if ($Mode -eq [System.IO.FileMode]::Open -and -not [IO.File]::Exists($Path)) { return $null }
9709|        try { return (New-Object System.IO.FileStream($Path, $Mode, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None)) } catch {
9710|            if ($watch.ElapsedMilliseconds -ge $WaitMs) { return $null }
9711|            Start-Sleep -Milliseconds 50
9712|        }
9713|    }
