10133|# A POST (Invoke-TelemetryRequest) - kept for the callers of wave 28.
10134|function Invoke-TelemetryPost {
10135|    param([string]$Url, [string]$Body, [int]$ConnectMs = 3000, [int]$TotalMs = 8000)
10136|    return (Invoke-TelemetryRequest -Url $Url -Body $Body -Method 'POST' -ConnectMs $ConnectMs -TotalMs $TotalMs)
10137|}
10138|
10139|# POSTs with the intake's rate rule: a 429 whose Retry-After is at most 60 s - and (wave 28b, D2)
10140|# fits into $BudgetMs, what is left of the flush's deadline (0: no deadline) - is waited for and the
10141|# SAME request sent once more; a longer or missing Retry-After, or a second 429, stops there. No
10142|# other retry. Every request is bounded by $TotalMs (and by the budget).
10143|function Invoke-TelemetrySend {
10144|    param([string]$Url, [string]$Body, [int]$ConnectMs = 3000, [int]$TotalMs = 8000, [long]$BudgetMs = 0)
10145|    $watch = [System.Diagnostics.Stopwatch]::StartNew()
10146|    $one = { param([long]$Left) if ($BudgetMs -gt 0) { [int][Math]::Max(100, [Math]::Min([long]$TotalMs, $Left)) } else { $TotalMs } }
10147|    $r = Invoke-TelemetryPost -Url $Url -Body $Body -ConnectMs $ConnectMs -TotalMs (& $one ($BudgetMs - $watch.ElapsedMilliseconds))
10148|    if ($r.Status -eq 429) {
10149|        $left = $BudgetMs - $watch.ElapsedMilliseconds
10150|        if ($r.RetryAfter -ge 0 -and $r.RetryAfter -le $script:TelemetryRetryAfterMax -and ($BudgetMs -le 0 -or ([long]$r.RetryAfter * 1000 + 1000) -lt $left)) {
10151|            Start-Sleep -Seconds $r.RetryAfter
10152|            $r = Invoke-TelemetryPost -Url $Url -Body $Body -ConnectMs $ConnectMs -TotalMs (& $one ($BudgetMs - $watch.ElapsedMilliseconds))
10153|            if ($r.Status -eq 429) { $r.Why = 'HTTP 429 again after its Retry-After' }
10154|        } elseif ($r.RetryAfter -ge 0 -and $r.RetryAfter -le $script:TelemetryRetryAfterMax) {
10155|            $r.Why = "HTTP 429 (Retry-After $($r.RetryAfter) s does not fit into the flush's deadline: not retried now)"
10156|        } else {
10157|            $r.Why = "HTTP 429 (Retry-After $(if ($r.RetryAfter -ge 0) { "$($r.RetryAfter) s, more than $($script:TelemetryRetryAfterMax) s" } else { 'not given' }): not retried now)"
10158|        }
10159|    }
10160|    return $r
10161|}
