9543|# 'powershell 5.1' (Windows PowerShell) | 'pwsh 7.x'.
9544|function Get-TelemetryRuntime {
9545|    $v = $PSVersionTable.PSVersion
9546|    return "$(if ($script:LegacyPS) { 'powershell' } else { 'pwsh' }) $($v.Major).$($v.Minor)"
9547|}
