9549|# A value of the event from a closed pattern: the value when it matches, else $Other ('' in:
9550|# $Empty).
9551|function Get-TelemetryToken {
9552|    param([string]$Value, [string]$Pattern, [string]$Empty = 'unknown', [string]$Other = 'other')
9553|    $v = ([string]$Value).Trim()
9554|    if (-not $v) { return $Empty }
9555|    if ($v -cmatch $Pattern) { return $v }
9556|    return $Other
9557|}
9558|
9559|# A non-negative whole number of the entry, or $null.
9560|function Get-TelemetryCount {
9561|    param($Value)
9562|    if ($null -eq $Value) { return $null }
9563|    $n = [long]0
9564|    if ([long]::TryParse([string]$Value, [System.Globalization.NumberStyles]::Integer, $script:Invariant, [ref]$n) -and $n -ge 0) { return $n }
9565|    return $null
9566|}
