9568|# The outcome of a committed ledger entry: { Outcome - usable | usable-after-continuation |
9569|# failed:<class>; Severity - info (usable) | warning (a provider limit or auth failure, or the
9570|# operator's -Kick) | error (every other failure); Class }. The class is the provider failure's
9571|# (auth, quota, capability, transport, permission, operator, unknown), else from the outcome:
9572|# timeout, stalled, or bridge (a failure of the bridge or the engine without a provider class).
9573|function Get-TelemetryOutcome {
9574|    param($Entry)
9575|    $bo = [string](Get-PropertyValue $Entry 'bridge_outcome' '')
9576|    if (Test-UsableOutcome $bo) {
9577|        $o = $(if ($bo -like '*after a timeout continuation*') { 'usable-after-continuation' } else { 'usable' })
9578|        return [pscustomobject]@{ Outcome = $o; Severity = 'info'; Class = '' }
9579|    }
9580|    $cls = [string](Get-PropertyValue (Get-PropertyValue $Entry 'provider_failure' $null) 'class' '')
9581|    if (-not $cls) {
9582|        if ($bo -like 'failed: timeout*') { $cls = 'timeout' }
9583|        elseif ($bo -like 'failed: stalled*') { $cls = 'stalled' }
9584|        elseif ($bo -like '*stopped by the operator*') { $cls = 'operator' }
9585|        else { $cls = 'bridge' }
9586|    }
9587|    if ($script:TelemetryFailureClasses -cnotcontains $cls) { $cls = 'unknown' }
9588|    $sev = $(if (@('auth', 'quota', 'operator') -contains $cls) { 'warning' } else { 'error' })
9589|    return [pscustomobject]@{ Outcome = "failed:$cls"; Severity = $sev; Class = $cls }
9590|}
9591|
9592|# (wave 28b, D1) The vendor class of a ledger entry's reviewer ($script:TelemetryVendors): the
9593|# engine's class (agy, muse), else the class of the endpoint's HOST - the base_url the ledger
9594|# recorded (reviewer.provider_config.base_url), or the built-in openai provider without one - else
9595|# 'other'. Returns the table row, or $null ('other').
9596|function Get-TelemetryVendor {
9597|    param($Reviewer)
9598|    $engine = [string](Get-PropertyValue $Reviewer 'engine' '')
9599|    if (-not $engine) { $engine = 'codex' }
9600|    if ($engine -ne 'codex') { return (@($script:TelemetryVendors | Where-Object { $_.Engine -and $_.Engine -ceq $engine }) | Select-Object -First 1) }
